sys_script.script:
(function executeRule(current, previous) {
    function isTrue(v) { return v == '1' || v == 'true'; }
    function stop(msg) { gs.addErrorMessage(msg); current.setAbortAction(true); }

    var other = new GlideRecord(current.getTableName());
    other.addQuery('sys_id', '!=', current.getUniqueValue());
    other.setLimit(1);
    other.query();
    if (other.hasNext()) return stop('Only one Doppel TI Configuration is allowed. Open the existing record and edit it instead.');

    var v2 = current.getValue('api_version') == 'v2';
    var missing = [];
    if (v2) {
        if (!String(current.getValue('client_id') || '').trim()) missing.push('Client ID');
        if (current.client_secret.nil()) missing.push('Client secret');
    } else {
        if (current.api_key.nil()) missing.push('API key');
        if (current.user_api_key.nil()) missing.push('User API key');
    }
    if (missing.length) return stop('Required for ' + (v2 ? 'v2' : 'v1') + ': ' + missing.join(', ') + '.');

    // Products: only checked when "Import all Doppel products" is unticked
    if (!isTrue(current.getValue('import_all_doppel_products'))) {
        var PRODUCT_FIELDS = ['import_domains', 'import_email', 'import_telco', 'import_social_media', 'import_dark_web',
                              'import_mobile_apps', 'import_ecommerce', 'import_crypto', 'import_paid_ads'];
        var anyProduct = false;
        for (var p = 0; p < PRODUCT_FIELDS.length; p++) {
            if (isTrue(current.getValue(PRODUCT_FIELDS[p]))) anyProduct = true;
        }
        if (!anyProduct) return stop('Select at least one product to import, or tick "Import all Doppel products" (Import tab).');
    }

	// Indicator rules: each group needs at least one ticked value, otherwise nothing can ever be promoted
    var GROUPS = {
        'Queue state': ['promote_queue_needs_confirmation', 'promote_queue_monitoring', 'promote_queue_actioned'],
        'Entity state': ['promote_entity_active', 'promote_entity_suspicious', 'promote_entity_parked'],
        'Severity': ['promote_severity_high', 'promote_severity_medium']
    };
    for (var g in GROUPS) {
        var anyTicked = false;
        for (var f = 0; f < GROUPS[g].length; f++) {
            if (isTrue(current.getValue(GROUPS[g][f]))) anyTicked = true;
        }
        if (!anyTicked) return stop('Indicator rules: tick at least one value under ' + g + '.');
    }

    var credFields = ['api_version', 'api_key', 'user_api_key', 'organisation_code', 'client_id', 'client_secret'];
    var credChanged = current.isNewRecord();
    for (var i = 0; i < credFields.length; i++) {
        if (current[credFields[i]].changes()) credChanged = true;
    }
    var verified = isTrue(current.getValue('connectivity_verified'));
    if (credChanged && (!verified || !current.last_tested.changes()))
        return stop('Click Test Connectivity and get a successful result before saving changed connection settings.');

    var days = parseInt(current.getValue('historical_days'), 10) || 0;
    if (days < 1 || days > 30) return stop('Historical days must be between 1 and 30.');
    if ((parseInt(current.getValue('import_interval_minutes'), 10) || 0) < 5) return stop('Import interval must be at least 5 minutes.');
})(current, previous);
